# IPTVPremium: capas e miniaturas menores do TMDB na base restaurada. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Allowed = @('FCCA9BA0B3EABD47EA5FEEB260B3CB347352B1A93782392E68D801A39B7ED8C0'); MayCreate = $false; After = '1AD2A4FCA17DAAC15F4E88EA58698D49B8CF46806902F817D71E318352705885'; PayloadHash = '1AD2A4FCA17DAAC15F4E88EA58698D49B8CF46806902F817D71E318352705885'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/AppNavigation.kt'; Allowed = @('1C899B5D866E0C1EF53955AC2708E00C6562BC8E7D5B8EE75DC13383762D8771'); MayCreate = $false; After = '520D3E298958CDF832B16E64128D71C71B98A23D04F9F87BA7A61554CAEC71EE'; PayloadHash = '520D3E298958CDF832B16E64128D71C71B98A23D04F9F87BA7A61554CAEC71EE'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieDetailsScreen.kt'; Allowed = @('45B058A212C7B95F7DCF4BDB5438E06A49A04E72CA9D2E17A5A8E661CDE8FF15'); MayCreate = $false; After = '1A2DAA1CF06F548540220675AF255F68DFDB6052E89CB22CB2DB8BE52CBFB7FB'; PayloadHash = '1A2DAA1CF06F548540220675AF255F68DFDB6052E89CB22CB2DB8BE52CBFB7FB'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterDownloadUrl.kt'; Allowed = @(); MayCreate = $true; After = 'E46336F71728E6CE938CE092D82155A4E004F6C955AF6E56F1F71DA72BD8627F'; PayloadHash = 'E46336F71728E6CE938CE092D82155A4E004F6C955AF6E56F1F71DA72BD8627F'; Data = '' },
    @{ Path = 'app/src/androidTest/java/br/com/flaviotorres/iptvpremium/data/cache/PosterDownloadUrlDeviceTest.kt'; Allowed = @(); MayCreate = $true; After = '544BD78551E514F4401CF207FCCAFBC50B1EF4224E09814FA2CBBB74F87E1FA5'; PayloadHash = '544BD78551E514F4401CF207FCCAFBC50B1EF4224E09814FA2CBBB74F87E1FA5'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/ImportTuningPolicy.kt'; Allowed = @('988F76E35E53086CE09BDA92D4B200F7C9989693C26029A4E2644AE4A4801150'); MayCreate = $false; After = '988F76E35E53086CE09BDA92D4B200F7C9989693C26029A4E2644AE4A4801150'; PayloadHash = '988F76E35E53086CE09BDA92D4B200F7C9989693C26029A4E2644AE4A4801150'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterBatchPolicy.kt'; Allowed = @('390D9614D71818EB2B26DA3F4FE5061EA3927C71AA23D51046CCD81750166E44'); MayCreate = $false; After = '390D9614D71818EB2B26DA3F4FE5061EA3927C71AA23D51046CCD81750166E44'; PayloadHash = '390D9614D71818EB2B26DA3F4FE5061EA3927C71AA23D51046CCD81750166E44'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterNetworkBudget.kt'; Allowed = @('E825A05A2CD8AF7992B3C294DB76952D929AC8117664F9B3D23F299E627EE21D'); MayCreate = $false; After = 'E825A05A2CD8AF7992B3C294DB76952D929AC8117664F9B3D23F299E627EE21D'; PayloadHash = 'E825A05A2CD8AF7992B3C294DB76952D929AC8117664F9B3D23F299E627EE21D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogGridNavigation.kt'; Allowed = @('4B4BA3F4B25423D1E170CB90E94F7807867298C13F36286E456733B35389DBEE'); MayCreate = $false; After = '4B4BA3F4B25423D1E170CB90E94F7807867298C13F36286E456733B35389DBEE'; PayloadHash = '4B4BA3F4B25423D1E170CB90E94F7807867298C13F36286E456733B35389DBEE'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogScrollMotion.kt'; Allowed = @('C173668CA4126A749DA9AE594FC8103E4260606DA6F2B3EC5901A2119A222145'); MayCreate = $false; After = 'C173668CA4126A749DA9AE594FC8103E4260606DA6F2B3EC5901A2119A222145'; PayloadHash = 'C173668CA4126A749DA9AE594FC8103E4260606DA6F2B3EC5901A2119A222145'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/components/CatalogTwoRowFrame.kt'; Allowed = @('E3D2367B59510A82F205C2DFD2D4BAB89B2459F8D9937C4523A14F870020C375'); MayCreate = $false; After = 'E3D2367B59510A82F205C2DFD2D4BAB89B2459F8D9937C4523A14F870020C375'; PayloadHash = 'E3D2367B59510A82F205C2DFD2D4BAB89B2459F8D9937C4523A14F870020C375'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieOpeningPolicy.kt'; Allowed = @('C8BBFF429BDCAD13BB31BE85BBA73159721D596C810A66FF4BF3B2A6831B26FC'); MayCreate = $false; After = 'C8BBFF429BDCAD13BB31BE85BBA73159721D596C810A66FF4BF3B2A6831B26FC'; PayloadHash = 'C8BBFF429BDCAD13BB31BE85BBA73159721D596C810A66FF4BF3B2A6831B26FC'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/PosterResolution.kt'; Allowed = @('DD8D08CD2127B89A90CD2E444DACA5B3E1C59931CF799ACFB23A35C0085087B0'); MayCreate = $false; After = 'DD8D08CD2127B89A90CD2E444DACA5B3E1C59931CF799ACFB23A35C0085087B0'; PayloadHash = 'DD8D08CD2127B89A90CD2E444DACA5B3E1C59931CF799ACFB23A35C0085087B0'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = Get-TextHash $original
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/capas-tmdb-menores-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: capas TMDB w342 e miniaturas de episodios w300; links originais preservados no cache e como alternativa.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
